package cn.lims.document;

import cn.lims.audit.AuditService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.nio.charset.StandardCharsets;
import java.io.ByteArrayInputStream;
import java.util.Base64;
import java.util.List;
import org.apache.poi.hwpf.HWPFDocument;
import org.apache.poi.hwpf.extractor.WordExtractor;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.extractor.XWPFWordExtractor;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1")
public class DocumentController {
    private final JdbcTemplate jdbc; private final AuditService audit;
    public DocumentController(JdbcTemplate jdbc,AuditService audit){this.jdbc=jdbc;this.audit=audit;}

    @GetMapping("/documents") @PreAuthorize("hasAuthority('document:file:view')")
    public List<DocumentRow> list(){return jdbc.query("select d.id,d.document_no,d.title,d.category,d.security_level,d.owner_dept_id,coalesce(dp.name,''),d.status,d.current_version_no,d.updated_at,d.version from doc_controlled d left join sys_department dp on dp.id=d.owner_dept_id where d.deleted=false order by d.id desc",(r,n)->new DocumentRow(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),nullable(r,6),r.getString(7),r.getString(8),r.getString(9),r.getObject(10,LocalDateTime.class),r.getInt(11)));}
    @PostMapping("/documents") @Transactional @PreAuthorize("hasAuthority('document:file:manage')")
    public Id create(@Valid @RequestBody DocumentRequest q,Authentication a){byte[] content=decodeFile(q.fileContentBase64());Long id=jdbc.queryForObject("insert into doc_controlled(document_no,title,category,security_level,owner_dept_id,current_version_no,created_by) values(?,?,?,?,?,?,?) returning id",Long.class,q.documentNo(),q.title(),q.category(),q.securityLevel(),q.ownerDeptId(),q.versionNo(),userId(a));Long vid=jdbc.queryForObject("insert into doc_version(document_id,version_no,file_name,storage_path,file_content,file_content_type,file_size,revision_note,review_due_at) values(?,?,?,?,?,?,?,?,?) returning id",Long.class,id,q.versionNo(),q.fileName(),q.storagePath(),content,q.fileContentType(),q.fileSize(),q.revisionNote(),q.reviewDueAt());audit.record(a,"document:file:create","DOCUMENT",id,null,"version="+vid);return new Id(id);}
    @PutMapping("/documents/{id}") @Transactional @PreAuthorize("hasAuthority('document:file:manage')")
    public void update(@PathVariable long id,@Valid @RequestBody DocumentRequest q,Authentication a){String status=jdbc.queryForObject("select status from doc_controlled where id=? and deleted=false",String.class,id);if(!"DRAFT".equals(status)&&!"REJECTED".equals(status))throw new IllegalArgumentException("仅草稿或退回文件可修改");if(jdbc.update("update doc_controlled set title=?,category=?,security_level=?,owner_dept_id=?,updated_at=current_timestamp,version=version+1 where id=? and version=?",q.title(),q.category(),q.securityLevel(),q.ownerDeptId(),id,q.version())==0)throw new IllegalArgumentException("文件不存在或已被修改");byte[] content=q.fileContentBase64()==null||q.fileContentBase64().isBlank()?null:decodeFile(q.fileContentBase64());if(content==null)jdbc.update("update doc_version set revision_note=?,review_due_at=? where document_id=? and version_no=? and status in('DRAFT','REJECTED')",q.revisionNote(),q.reviewDueAt(),id,q.versionNo());else jdbc.update("update doc_version set file_name=?,storage_path=?,file_content=?,file_content_type=?,file_size=?,revision_note=?,review_due_at=? where document_id=? and version_no=? and status in('DRAFT','REJECTED')",q.fileName(),q.storagePath(),content,q.fileContentType(),q.fileSize(),q.revisionNote(),q.reviewDueAt(),id,q.versionNo());audit.record(a,"document:file:update","DOCUMENT",id,null,q.toString());}
    @DeleteMapping("/documents/{id}") @Transactional @PreAuthorize("hasAuthority('document:file:manage')")
    public void delete(@PathVariable long id,Authentication a){if(jdbc.update("update doc_controlled set deleted=true,updated_at=current_timestamp where id=? and deleted=false and status in('DRAFT','REJECTED')",id)==0)throw new IllegalArgumentException("仅草稿或退回文件可以删除");audit.record(a,"document:file:delete","DOCUMENT",id,null,"deleted");}
    @PostMapping("/documents/{id}/versions") @Transactional @PreAuthorize("hasAuthority('document:file:manage')")
    public Id newVersion(@PathVariable long id,@Valid @RequestBody VersionRequest q,Authentication a){String status=jdbc.queryForObject("select status from doc_controlled where id=? and deleted=false",String.class,id);if(!"PUBLISHED".equals(status))throw new IllegalArgumentException("仅已发布文件可发起修订");Long vid=jdbc.queryForObject("insert into doc_version(document_id,version_no,file_name,storage_path,revision_note,review_due_at) values(?,?,?,?,?,?) returning id",Long.class,id,q.versionNo(),q.fileName(),q.storagePath(),q.revisionNote(),q.reviewDueAt());jdbc.update("update doc_controlled set status='DRAFT',current_version_no=?,updated_at=current_timestamp,version=version+1 where id=?",q.versionNo(),id);audit.record(a,"document:version:create","DOCUMENT_VERSION",vid,null,q.versionNo());return new Id(vid);}
    @GetMapping("/documents/{id}/versions") @PreAuthorize("hasAuthority('document:file:view')")
    public List<VersionRow> versions(@PathVariable long id){return jdbc.query("select id,version_no,file_name,storage_path,revision_note,status,review_due_at,effective_at,review_comment,created_at from doc_version where document_id=? order by id desc",(r,n)->new VersionRow(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getObject(7,LocalDate.class),r.getObject(8,LocalDateTime.class),r.getString(9),r.getObject(10,LocalDateTime.class)),id);}
    @GetMapping("/documents/{id}/download") @PreAuthorize("hasAuthority('document:file:view')")
    public ResponseEntity<byte[]> download(@PathVariable long id){var rows=jdbc.queryForList("select v.file_name,v.file_content,v.file_content_type from doc_controlled d join doc_version v on v.document_id=d.id and v.version_no=d.current_version_no where d.id=? and d.deleted=false and d.status='PUBLISHED'",id);if(rows.isEmpty())throw new IllegalArgumentException("仅已发布文件可以下载");var row=rows.get(0);byte[] content=(byte[])row.get("file_content");if(content==null)throw new IllegalArgumentException("该文件尚未存储附件内容");String name=(String)row.get("file_name");String type=(String)row.get("file_content_type");HttpHeaders headers=new HttpHeaders();headers.setContentDisposition(ContentDisposition.attachment().filename(name==null?"document":name,StandardCharsets.UTF_8).build());headers.setContentType(type==null||type.isBlank()?MediaType.APPLICATION_OCTET_STREAM:MediaType.parseMediaType(type));return ResponseEntity.ok().headers(headers).contentLength(content.length).body(content);}
    @GetMapping("/documents/{id}/preview-text") @PreAuthorize("hasAuthority('document:file:view')")
    public Preview previewText(@PathVariable long id){var row=publishedFile(id);String name=String.valueOf(row.get("file_name")).toLowerCase();byte[] content=(byte[])row.get("file_content");try{if(name.endsWith(".docx")){try(var doc=new XWPFDocument(new ByteArrayInputStream(content));var extractor=new XWPFWordExtractor(doc)){return new Preview("WORD","<div class='word-preview'>"+paragraphs(extractor.getText())+"</div>");}}if(name.endsWith(".doc")){try(var doc=new HWPFDocument(new ByteArrayInputStream(content));var extractor=new WordExtractor(doc)){return new Preview("WORD","<div class='word-preview'>"+paragraphs(extractor.getText())+"</div>");}}if(name.endsWith(".xlsx")||name.endsWith(".xls")){try(var workbook=WorkbookFactory.create(new ByteArrayInputStream(content))){DataFormatter formatter=new DataFormatter();StringBuilder html=new StringBuilder();for(Sheet sheet:workbook){html.append("<h3>").append(escape(sheet.getSheetName())).append("</h3><table>");for(Row rowData:sheet){html.append("<tr>");for(Cell cell:rowData)html.append("<td>").append(escape(formatter.formatCellValue(cell))).append("</td>");html.append("</tr>");}html.append("</table>");}return new Preview("EXCEL",html.toString());}}throw new IllegalArgumentException("该文件类型请使用原文件预览");}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("文件预览解析失败");}}
    @PostMapping("/document-versions/{id}/submit") @Transactional @PreAuthorize("hasAuthority('document:file:manage')")
    public void submit(@PathVariable long id,Authentication a){Long doc=docId(id);if(jdbc.update("update doc_version set status='REVIEWING',submitted_by=?,submitted_at=current_timestamp where id=? and status in('DRAFT','REJECTED')",userId(a),id)==0)throw new IllegalArgumentException("版本状态不允许提交");jdbc.update("update doc_controlled set status='REVIEWING',updated_at=current_timestamp where id=?",doc);audit.record(a,"document:version:submit","DOCUMENT_VERSION",id,"DRAFT","REVIEWING");}
    @PostMapping("/document-versions/{id}/review") @Transactional @PreAuthorize("hasAuthority('document:file:review')")
    public void review(@PathVariable long id,@RequestBody Decision q,Authentication a){Long doc=docId(id);String target=q.approved()?"APPROVED":"REJECTED";if(jdbc.update("update doc_version set status=?,reviewed_by=?,reviewed_at=current_timestamp,review_comment=? where id=? and status='REVIEWING'",target,userId(a),q.comment(),id)==0)throw new IllegalArgumentException("仅审核中文件可处理");jdbc.update("update doc_controlled set status=?,updated_at=current_timestamp where id=?",target,doc);audit.record(a,"document:version:review","DOCUMENT_VERSION",id,"REVIEWING",target);}
    @PostMapping("/document-versions/{id}/publish") @Transactional @PreAuthorize("hasAuthority('document:file:publish')")
    public void publish(@PathVariable long id,Authentication a){Long doc=docId(id);if(jdbc.update("update doc_version set status='PUBLISHED',published_by=?,published_at=current_timestamp,effective_at=current_timestamp where id=? and status='APPROVED'",userId(a),id)==0)throw new IllegalArgumentException("仅审核通过版本可发布");jdbc.update("update doc_version set status='SUPERSEDED' where document_id=? and id<>? and status='PUBLISHED'",doc,id);String ver=jdbc.queryForObject("select version_no from doc_version where id=?",String.class,id);jdbc.update("update doc_controlled set status='PUBLISHED',current_version_no=?,updated_at=current_timestamp where id=?",ver,doc);audit.record(a,"document:version:publish","DOCUMENT_VERSION",id,"APPROVED","PUBLISHED");}
    @PostMapping("/documents/{id}/void") @Transactional @PreAuthorize("hasAuthority('document:file:publish')")
    public void voidDoc(@PathVariable long id,@RequestBody(required=false) Decision q,Authentication a){if(jdbc.update("update doc_controlled set status='VOID',updated_at=current_timestamp where id=? and status='PUBLISHED'",id)==0)throw new IllegalArgumentException("仅已发布文件可作废");jdbc.update("update doc_version set status='VOID' where document_id=? and status='PUBLISHED'",id);audit.record(a,"document:file:void","DOCUMENT",id,null,q==null?"VOID":q.comment());}
    @GetMapping("/documents/review-due") @PreAuthorize("hasAuthority('document:file:view')")
    public List<VersionRow> reviewDue(){return jdbc.query("select id,version_no,file_name,storage_path,revision_note,status,review_due_at,effective_at,review_comment,created_at from doc_version where status='PUBLISHED' and review_due_at<=current_date+30 order by review_due_at",(r,n)->new VersionRow(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getObject(7,LocalDate.class),r.getObject(8,LocalDateTime.class),r.getString(9),r.getObject(10,LocalDateTime.class)));}
    private Long docId(long versionId){return jdbc.queryForObject("select document_id from doc_version where id=?",Long.class,versionId);}
    private Long userId(Authentication a){return jdbc.queryForObject("select id from sys_user where username=? and deleted=false",Long.class,a.getName());}
    private byte[] decodeFile(String value){if(value==null||value.isBlank())throw new IllegalArgumentException("请选择文件");try{String payload=value.contains(",")?value.substring(value.indexOf(',')+1):value;return Base64.getDecoder().decode(payload);}catch(IllegalArgumentException e){throw new IllegalArgumentException("文件内容格式错误");}}
    private java.util.Map<String,Object> publishedFile(long id){var rows=jdbc.queryForList("select v.file_name,v.file_content from doc_controlled d join doc_version v on v.document_id=d.id and v.version_no=d.current_version_no where d.id=? and d.deleted=false and d.status='PUBLISHED'",id);if(rows.isEmpty())throw new IllegalArgumentException("仅已发布文件可以预览");if(rows.get(0).get("file_content")==null)throw new IllegalArgumentException("该文件尚未存储附件内容");return rows.get(0);}
    private String paragraphs(String text){StringBuilder html=new StringBuilder();for(String line:text.split("\\R")){if(!line.isBlank())html.append("<p>").append(escape(line)).append("</p>");}return html.toString();}
    private String escape(String value){return String.valueOf(value).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    private static Long nullable(java.sql.ResultSet r,int i)throws java.sql.SQLException{long v=r.getLong(i);return r.wasNull()?null:v;}
    public record Id(Long id){}
    public record DocumentRow(long id,String documentNo,String title,String category,String securityLevel,Long ownerDeptId,String departmentName,String status,String currentVersionNo,LocalDateTime updatedAt,int version){}
    public record DocumentRequest(@NotBlank String documentNo,@NotBlank String title,@NotBlank String category,@NotBlank String securityLevel,Long ownerDeptId,@NotBlank String versionNo,String fileName,String storagePath,String fileContentBase64,String fileContentType,Long fileSize,String revisionNote,LocalDate reviewDueAt,int version){}
    public record VersionRequest(@NotBlank String versionNo,String fileName,String storagePath,String revisionNote,LocalDate reviewDueAt){}
    public record VersionRow(long id,String versionNo,String fileName,String storagePath,String revisionNote,String status,LocalDate reviewDueAt,LocalDateTime effectiveAt,String reviewComment,LocalDateTime createdAt){}
    public record Decision(boolean approved,String comment){}
    public record Preview(String type,String html){}
}
